import withSerwistInit from "@serwist/next";
import type { NextConfig } from "next";
import { createHash } from "node:crypto";
import { readdirSync, readFileSync } from "node:fs";

type Catalog = { systems: { id: string; gameCount: number }[]; games: { slug: string }[] };

// Generated by scripts/prepare-assets.mjs (runs as predev/prebuild).
const catalog: Catalog = JSON.parse(readFileSync("./lib/generated/catalog.json", "utf8"));
const revision = `${Date.now()}`;

// Every statically exported route, so the whole UI works offline from first install.
const routes = [
  "/",
  "/settings",
  "/offline",
  ...catalog.systems.map((s) => `/system/${s.id}`),
  ...catalog.games.map((g) => `/play/${g.slug}`),
];

// Small public files to precache. (Serwist skips its own public glob when
// additionalPrecacheEntries is set.) ROMs/cores/splash are deliberately excluded.
const publicFiles = ["packs.json", ...readdirSync("public/icons").map((f) => `icons/${f}`)].map((f) => ({
  url: `/${f}`,
  revision: createHash("md5").update(readFileSync(`public/${f}`)).digest("hex"),
}));

const withSerwist = withSerwistInit({
  swSrc: "app/sw.ts",
  swDest: "public/sw.js",
  disable: process.env.NODE_ENV === "development",
  additionalPrecacheEntries: [
    { url: "/manifest.webmanifest", revision },
    ...publicFiles,
    ...routes.flatMap((r) => [
      { url: r === "/" ? "/index.html" : `${r}.html`, revision },
      { url: r === "/" ? "/index.txt" : `${r}.txt`, revision },
    ]),
  ],
});

const nextConfig: NextConfig = {
  output: "export",
  images: { unoptimized: true },
  reactStrictMode: true,
};

export default withSerwist(nextConfig);
